sp_widget.client_script:
api.controller = function($scope) {
  var c = this;

  // Populate dropdowns
  $scope.locations = c.data.locations;
  $scope.managers = c.data.managers;
  $scope.subjects = c.data.subjects;
	$scope.speakers = c.data.speakers;

  // Submit form function
  $scope.submitForm = function() {
  // Validate form before proceeding
  if (!$scope.conferenceForm.$valid) {
    alert("Please fill out all required fields before submitting.");
    return; // Stop further execution
  }

  // Ensure that the conference end date is not before the current date
  var today = new Date();
  var endDate = new Date($scope.conferenceEnd);

  if (endDate < today) {
    alert("The end date cannot be in the past. Please select a valid end date.");
    return;  // Stop form submission if the end date is invalid
  }

    var formData = {
      action: 'createNewConference',
      conferenceDetails: {
        conferenceName: $scope.conferenceName,
        selectedLocation: $scope.selectedLocation,
        conferenceStart: $scope.conferenceStart,
        conferenceEnd: $scope.conferenceEnd,
        selectedManager: $scope.selectedManager,
        selectedSubjectOption: $scope.selectedSubjectOption,
				conferenceDescription: $scope.conferenceDescription,
				selectedSpeaker: $scope.selectedSpeaker
      }
    };

    console.log("Submitting Form Data:", formData);

    // Use .get(formData) to send form data
    c.server.get(formData).then(function(response) {
      console.log("Server responded:", response);

      if (response.data && response.data.responseResult !== "FAILURE") {
        alert("Conference created successfully!");

        // Clear form fields
        $scope.conferenceName = '';
        $scope.selectedLocation = '';
        $scope.conferenceStart = '';
        $scope.conferenceEnd = '';
        $scope.selectedManager = '';
        $scope.selectedSubjectOption = '';
				$scope.conferenceDescription = '';
				$scope.selectedSpeaker = '';
       } else {
        alert("Failed to create conference.");
      }
    });
  };
};

sp_widget.css:
/* Make the form container a nice centered card */
form[name="conferenceForm"] {
  background: #ffffff;
  padding: 30px;
  border-radius: 12px;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);
  max-width: 600px;
  margin: 30px auto;
}

/* Style labels and headings */
form[name="conferenceForm"] h3 {
  margin-top: 20px;
  font-size: 1.25rem;
  color: #333;
}

/* Style input fields and dropdowns */
form[name="conferenceForm"] input[type="text"],
form[name="conferenceForm"] input[type="date"],
form[name="conferenceForm"] select {
  margin-top: 8px;
  margin-bottom: 20px;
  width: 100%;
  padding: 10px;
  border: 1px solid #cccccc;
  border-radius: 6px;
  font-size: 1rem;
}

/* Style the Submit button */
form[name="conferenceForm"] button.btn-primary {
  background-color: #007bff;
  border: none;
  font-size: 1.1rem;
  padding: 12px 20px;
  border-radius: 8px;
  color: white;
  width: 100%;
  transition: background-color 0.3s ease;
}

/* Hover effect for Submit button */
form[name="conferenceForm"] button.btn-primary:hover {
  background-color: #0056b3;
  cursor: pointer;
}

/* Add red borders if validation fails */
.ng-invalid.ng-touched {
  border-color: #dc3545;
}

/* Optional: Improve appearance of alert popups (for mobile) */
.swal2-popup {
  font-size: 1.2rem !important;
}

sp_widget.script:
(function() {
  gs.info("Widget server script started.");

  // Populate dropdowns
  function populateDropdowns() {
    var locationList = [];
    var managerSet = new Set();
    var subjectList = [];
    var speakerList = [];

    // Locations
    var locationGR = new GlideRecord('cmn_location');
    locationGR.query();
    while (locationGR.next()) {
      locationList.push(locationGR.name.toString());
    }
    locationList.sort();

    // Managers with specific roles
    var roleId = ['ce3ae88383bb12100c1eb3a6feaad38a', 'ce3ae88383bb12100c1eb3a6feaad390'];
    var roleGR = new GlideRecord('sys_user_has_role');
    roleGR.addQuery('role', 'IN', roleId.join(','));
    roleGR.query();
    while (roleGR.next()) {
      if (roleGR.user) {
        managerSet.add(roleGR.user.name.toString());
      }
    }
    var managerList = Array.from(managerSet);
    managerList.sort();

    // Subjects from choice list
    var choiceGR = new GlideRecord('sys_choice');
    choiceGR.addQuery('name', 'x_1297629_confer_0_conferences');
    choiceGR.addQuery('element', 'subject');
    choiceGR.query();
    while (choiceGR.next()) {
      subjectList.push(choiceGR.label.toString());
    }
    subjectList.sort();

    // Speakers from custom speaker table
    var speakerGR = new GlideRecord('x_1297629_confer_0_speakers');
    speakerGR.query();
    while (speakerGR.next()) {
      speakerList.push(speakerGR.user.name.toString());
    }

    // Send to client
    data.locations = locationList;
    data.managers = managerList;
    data.subjects = subjectList;
    data.speakers = speakerList;
  }

  populateDropdowns();

  // Handle submission
  if (typeof input !== 'undefined' && input !== null) {
    gs.info("Input detected: " + JSON.stringify(input));

    if (input.action === 'createNewConference') {
      gs.info("Action detected: createNewConference");
      data.result = createNewConference(input.conferenceDetails);
    } else {
      gs.error("No action property found in input.");
    }
  }

  function createNewConference(details) {
    var locationSysId = '';
    var managerSysId = '';
    var speakerSysId = '';

    // Location sys_id
    if (details.selectedLocation) {
      var locGR = new GlideRecord('cmn_location');
      locGR.addQuery('name', details.selectedLocation);
      locGR.query();
      if (locGR.next()) {
        locationSysId = locGR.getUniqueValue();
      } else {
        gs.error("Location lookup failed for: " + details.selectedLocation);
      }
    }

    // Manager sys_id
    if (details.selectedManager) {
      var userGR = new GlideRecord('sys_user');
      userGR.addQuery('name', details.selectedManager);
      userGR.query();
      if (userGR.next()) {
        managerSysId = userGR.getUniqueValue();
      } else {
        gs.error("Manager lookup failed for: " + details.selectedManager);
      }
    }

    // Speaker sys_id (from speaker table now)
    if (details.selectedSpeaker) {
      var speakerGR = new GlideRecord('x_1297629_confer_0_speakers');
      if (speakerGR.get(details.selectedSpeaker)) {
        speakerSysId = speakerGR.getUniqueValue();
      } else {
        gs.error("Speaker record not found for sys_id: " + details.selectedSpeaker);
      }
    }

    // Create conference
    var confGR = new GlideRecord('x_1297629_confer_0_conferences');
    confGR.initialize();
    confGR.name = details.conferenceName || '';
    confGR.location = locationSysId || '';
    confGR.start_date = details.conferenceStart || '';
    confGR.end_date = details.conferenceEnd || '';
    confGR.manager = managerSysId || '';
    confGR.subject = details.selectedSubjectOption || '';
    confGR.description = details.conferenceDescription || '';

		// Active status logic
    if (details.conferenceEnd) {
      var today = new GlideDate();
      var endDate = new GlideDate();
      endDate.setDisplayValue(details.conferenceEnd);
      confGR.active = !endDate.before(today);
    } else {
      confGR.active = true;
    }

    // Insert and M2M record
    var newSysId = confGR.insert();
    if (newSysId) {
      gs.info("Conference created successfully. Sys ID: " + newSysId);

      if (speakerSysId) {
        var m2mGR = new GlideRecord('x_1297629_confer_0_m2m_x_1297629_co_x_1297629_co');
        m2mGR.initialize();
        m2mGR.x_1297629_confer_0_speakers = speakerSysId;
				m2mGR.x_1297629_confer_0_conferences = newSysId;
        var m2mInsert = m2mGR.insert();
        if (!m2mInsert) {
          gs.error("Failed to link speaker via M2M. Error: " + m2mGR.getLastErrorMessage());
        }
      }


      return { responseResult: 'SUCCESS', sysId: newSysId };
    } else {
      gs.error("Insert failed. Last Error: " + confGR.getLastErrorMessage());
      return { responseResult: 'FAILURE' };
    }
  }
})();
